public class RetryableTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        int[] n1 = {0};
        java.util.function.IntSupplier s1 = () -> { n1[0]++; return n1[0] >= 3 ? 7 : -1; };
        check("returns the first positive value", 7, Retryable.callUntilPositive(s1, 5));
        check("stops as soon as it succeeds", 3, n1[0]);

        int[] n2 = {0};
        java.util.function.IntSupplier s2 = () -> { n2[0]++; return 0; };
        check("no positive value -> -1", -1, Retryable.callUntilPositive(s2, 4));
        check("exhausts exactly maxCalls attempts", 4, n2[0]);

        int[] n3 = {0};
        java.util.function.IntSupplier s3 = () -> { n3[0]++; return 100; };
        check("immediate success", 100, Retryable.callUntilPositive(s3, 5));
        check("only one call needed", 1, n3[0]);

        int[] n4 = {0};
        java.util.function.IntSupplier s4 = () -> { n4[0]++; return 5; };
        check("maxCalls 0 -> -1", -1, Retryable.callUntilPositive(s4, 0));
        check("maxCalls 0 makes no calls at all", 0, n4[0]);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

