public class Retryable {

    public static int callUntilPositive(java.util.function.IntSupplier source, int maxCalls) {
        for (int i = 0; i < maxCalls; i++) {
            int value = source.getAsInt();
            if (value > 0) {
                return value;
            }
        }
        return -1;
    }
}
